                post_hook={
                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; CREATE OR REPLACE TABLE snitch_db.maplemonk.qcom_replen_1_July2025_KNOT AS WITH sizeCombsFromInv AS ( SELECT sku_group, sku, SIZE, SUM(OPENING_INVENTORY) AS stock_qty, CASE WHEN sku LIKE \'SN%\' OR sku LIKE \'4MSFR%\' OR sku LIKE \'BP%\' THEN \'NA\' WHEN sku LIKE \'SH%\' THEN CASE when SIZE = \'39\' THEN \'XS\' when SIZE = \'40\' THEN \'S\' when SIZE = \'41\' THEN \'M\' when SIZE= \'42\' THEN \'L\' when SIZE = \'43\' THEN \'XL\' when SIZE = \'44\' THEN \'XXL\' when SIZE= \'45\' THEN \'3XL\' ELSE \'NA\' END ELSE CASE when SIZE = \'28\' THEN \'XS\' when SIZE = \'30\' THEN \'S\' when SIZE = \'32\' THEN \'M\' when SIZE = \'34\' THEN \'L\' when SIZE = \'36\' THEN \'XL\' when SIZE = \'38\' THEN \'XXL\' when SIZE= \'40\' THEN \'3XL\' when SIZE = \'42\' THEN \'4XL\' when SIZE = \'44\' THEN \'5XL\' when SIZE = \'46\' THEN \'6XL\' when SIZE = \'48\' THEN \'7XL\' when SIZE = \'50\' THEN \'8XL\' when SIZE = \'XS\' THEN \'XS\' when SIZE = \'S\' THEN \'S\' when SIZE = \'M\' THEN \'M\' when SIZE = \'L\' THEN \'L\' when SIZE = \'XL\' THEN \'XL\' when SIZE = \'XXL\' THEN \'XXL\' when SIZE = \'3XL\' THEN \'3XL\' when SIZE = \'XXXL\' THEN \'3XL\' ELSE \'NA\' END END AS size_mapped FROM snitch_db.maplemonk.knot_inventory_report WHERE date = CURRENT_DATE AND sku NOT LIKE \'%CB%\' GROUP BY sku_group, sku,SIZE ), sizeCombsFromSales AS ( SELECT sku, sku_group, SIZE, CASE WHEN sku LIKE \'SN%\' OR sku LIKE \'4MSFR%\' OR sku LIKE \'BP%\' THEN \'NA\' WHEN sku LIKE \'SH%\' THEN CASE when SIZE = \'39\' THEN \'XS\' when SIZE = \'40\' THEN \'S\' when SIZE = \'41\' THEN \'M\' when SIZE= \'42\' THEN \'L\' when SIZE = \'43\' THEN \'XL\' when SIZE = \'44\' THEN \'XXL\' when SIZE= \'45\' THEN \'3XL\' ELSE \'NA\' END ELSE CASE when SIZE = \'28\' THEN \'XS\' when SIZE = \'30\' THEN \'S\' when SIZE = \'32\' THEN \'M\' when SIZE = \'34\' THEN \'L\' when SIZE = \'36\' THEN \'XL\' when SIZE = \'38\' THEN \'XXL\' when SIZE= \'40\' THEN \'3XL\' when SIZE = \'42\' THEN \'4XL\' when SIZE = \'44\' THEN \'5XL\' when SIZE = \'46\' THEN \'6XL\' when SIZE = \'48\' THEN \'7XL\' when SIZE = \'50\' THEN \'8XL\' when SIZE = \'XS\' THEN \'XS\' when SIZE = \'S\' THEN \'S\' when SIZE = \'M\' THEN \'M\' when SIZE = \'L\' THEN \'L\' when SIZE = \'XL\' THEN \'XL\' when SIZE = \'XXL\' THEN \'XXL\' when SIZE = \'3XL\' THEN \'3XL\' when SIZE = \'XXXL\' THEN \'3XL\' ELSE \'NA\' END END AS size_mapped, COUNT(*) AS units_sold FROM snitch_db.maplemonk.knot_fact_item WHERE order_date >= CURRENT_DATE - 7 GROUP BY sku, sku_group,SIZE ), relevant_sku_branches AS ( SELECT DISTINCT sku_group FROM sizeCombsFromInv UNION SELECT DISTINCT sku_group FROM sizeCombsFromSales ), relevant_sizes AS ( SELECT DISTINCT sku_group, size, size_mapped FROM sizeCombsFromInv UNION SELECT DISTINCT sku_group, size, size_mapped FROM sizeCombsFromSales ), valid_combinations AS ( SELECT rs.sku_group, rs.size, rs.size_mapped FROM relevant_sku_branches rb INNER JOIN relevant_sizes rs ON rb.sku_group = rs.sku_group ), sizeExtract AS ( SELECT vc.sku_group, vc.size, vc.size_mapped, COALESCE(q1.SKU, CONCAT(vc.sku_group, \'-\', vc.size)) AS SKU, COALESCE(q1.stock_qty, 0) AS stock_qty FROM valid_combinations vc LEFT JOIN sizeCombsFromInv q1 ON vc.sku_group = q1.sku_group AND vc.size = q1.size ), sizeExtractPivotUp AS ( SELECT sku_group, COALESCE(SUM(CASE WHEN size_mapped = \'XS\' THEN stock_qty ELSE 0 END), 0) AS XS_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'S\' THEN stock_qty ELSE 0 END), 0) AS S_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'M\' THEN stock_qty ELSE 0 END), 0) AS M_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'L\' THEN stock_qty ELSE 0 END), 0) AS L_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'XL\' THEN stock_qty ELSE 0 END), 0) AS XL_units_store, COALESCE(SUM(CASE WHEN size_mapped IN (\'XXL\', \'XXl\', \'2XL\') THEN stock_qty ELSE 0 END), 0) AS XXL_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'3XL\' THEN stock_qty ELSE 0 END), 0) AS XL3_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'4XL\' THEN stock_qty ELSE 0 END), 0) AS XL4_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'5XL\' THEN stock_qty ELSE 0 END), 0) AS XL5_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'6XL\' THEN stock_qty ELSE 0 END), 0) AS XL6_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'7XL\' THEN stock_qty ELSE 0 END), 0) AS XL7_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'8XL\' THEN stock_qty ELSE 0 END), 0) AS XL8_units_store, COALESCE(SUM(CASE WHEN size_mapped = \'NA\' THEN stock_qty ELSE 0 END), 0) AS NA_units_store FROM sizeExtract GROUP BY sku_group ), sizeCount AS ( SELECT sku_group, COUNT(DISTINCT CASE WHEN stock_qty > 0 THEN size END) AS num_size_available FROM sizeExtract GROUP BY sku_group ), ItemData AS ( WITH sales_data AS ( SELECT sku, sku_group, SIZE, CASE WHEN sku LIKE \'SN%\' OR sku LIKE \'4MSFR%\' OR sku LIKE \'BP%\' THEN \'NA\' WHEN sku LIKE \'SH%\' THEN CASE when SIZE = \'39\' THEN \'XS\' when SIZE = \'40\' THEN \'S\' when SIZE = \'41\' THEN \'M\' when SIZE= \'42\' THEN \'L\' when SIZE = \'43\' THEN \'XL\' when SIZE = \'44\' THEN \'XXL\' when SIZE= \'45\' THEN \'3XL\' ELSE \'NA\' END ELSE CASE when SIZE = \'28\' THEN \'XS\' when SIZE = \'30\' THEN \'S\' when SIZE = \'32\' THEN \'M\' when SIZE = \'34\' THEN \'L\' when SIZE = \'36\' THEN \'XL\' when SIZE = \'38\' THEN \'XXL\' when SIZE= \'40\' THEN \'3XL\' when SIZE = \'42\' THEN \'4XL\' when SIZE = \'44\' THEN \'5XL\' when SIZE = \'46\' THEN \'6XL\' when SIZE = \'48\' THEN \'7XL\' when SIZE = \'50\' THEN \'8XL\' when SIZE = \'XS\' THEN \'XS\' when SIZE = \'S\' THEN \'S\' when SIZE = \'M\' THEN \'M\' when SIZE = \'L\' THEN \'L\' when SIZE = \'XL\' THEN \'XL\' when SIZE = \'XXL\' THEN \'XXL\' when SIZE = \'3XL\' THEN \'3XL\' when SIZE = \'XXXL\' THEN \'3XL\' ELSE \'NA\' END END AS size_mapped, order_date, SUM(total_quantity) AS units_sold FROM snitch_db.maplemonk.knot_fact_item WHERE order_date >= CURRENT_DATE - INTERVAL \'45 DAYS\' AND sku not like (\'%4MCB%\') GROUP BY sku, sku_group, size, size_mapped, order_date ), first_sale AS ( SELECT sku_group, MIN(order_date) AS first_sale_date FROM sales_data GROUP BY sku_group ), total_sales AS ( SELECT s.sku, s.sku_group, s.size, s.size_mapped, f.first_sale_date, SUM(s.units_sold) AS total_units_sold, DATEDIFF(DAY, f.first_sale_date, CURRENT_DATE) AS days_elapsed FROM sales_data s LEFT JOIN first_sale f ON s.sku_group = f.sku_group GROUP BY s.sku, s.sku_group, s.size, s.size_mapped, f.first_sale_date ), sales_last_7_days AS ( SELECT s.sku, SUM(s.units_sold) AS units_sold_last_7_days FROM sales_data s LEFT JOIN first_sale f ON s.sku_group = f.sku_group WHERE s.order_date >= CASE WHEN DATEDIFF(DAY, f.first_sale_date, CURRENT_DATE) < 7 THEN f.first_sale_date ELSE CURRENT_DATE - INTERVAL \'7 DAYS\' END GROUP BY s.sku ) SELECT ts.sku, ts.sku_group, ts.size, ts.size_mapped, ts.first_sale_date, ts.total_units_sold, ts.days_elapsed, CASE WHEN ts.days_elapsed = 0 THEN 0 ELSE ROUND(ts.total_units_sold / NULLIF(ts.days_elapsed, 0), 2) END AS natural_rate_of_sale, COALESCE(sl7.units_sold_last_7_days, 0) AS units_sold_last_7_days, CASE WHEN ts.days_elapsed < 7 THEN ts.days_elapsed ELSE 7 END AS days_for_7_day_sales, CASE WHEN ts.days_elapsed = 0 THEN 0 ELSE ROUND(COALESCE(sl7.units_sold_last_7_days, 0) / NULLIF( CASE WHEN ts.days_elapsed < 7 THEN ts.days_elapsed ELSE 7 END, 0), 2) END AS seven_day_rate_of_sale FROM total_sales ts LEFT JOIN sales_last_7_days sl7 ON ts.sku = sl7.sku GROUP BY ts.sku, ts.sku_group, ts.size, ts.size_mapped, ts.first_sale_date, ts.total_units_sold, ts.days_elapsed, natural_rate_of_sale, units_sold_last_7_days, days_for_7_day_sales, seven_day_rate_of_sale ), CategoryUnitsSold AS ( SELECT sku_group, size_mapped, SUM(total_units_sold) AS category_units_sold FROM ItemData GROUP BY sku_group, size_mapped ), SizeRatio AS ( SELECT sku_group, size_mapped, SUM(total_units_sold) AS total_units_per_size, SUM(SUM(total_units_sold)) OVER (PARTITION BY sku_group) AS total_units_per_sku_group, ROUND((SUM(total_units_sold) / SUM(SUM(total_units_sold)) OVER (PARTITION BY sku_group)) * 100, 2) AS size_ratio_percentage FROM ItemData GROUP BY sku_group, size_mapped ), FinalData AS ( SELECT se.size, se.size_mapped, se.sku_group, se.SKU, se_pvup.XS_units_store, se_pvup.S_units_store, se_pvup.M_units_store, se_pvup.L_units_store, se_pvup.XL_units_store, se_pvup.XXL_units_store, se_pvup.XL3_units_store, se_pvup.XL4_units_store, se_pvup.XL5_units_store, se_pvup.XL6_units_store, se_pvup.XL7_units_store, se_pvup.XL8_units_store, se_pvup.NA_units_store, SUM(se.stock_qty) AS units_on_hand, sc.num_size_available, COALESCE(sr.size_ratio_percentage, 0) AS size_ratio_percentage, SUM(COALESCE(sr.size_ratio_percentage, 0)) OVER (PARTITION BY se.sku_group) AS sum_size_ratio_percentage_by_sku_group, sum(coalesce(ItemData.total_units_sold,0)) as final_units_sold, sum(coalesce(ItemData.natural_rate_of_sale,0)) as final_natural_rate_of_sale, sum(coalesce(ItemData.seven_day_rate_of_sale,0)) as final_seven_day_rate_of_sale, ItemData.first_sale_date, ItemData.days_elapsed FROM sizeExtract se JOIN sizeCount sc ON se.sku_group = sc.sku_group LEFT JOIN SizeRatio sr ON se.size_mapped = sr.size_mapped and se.sku_group=sr.sku_group LEFT JOIN sizeExtractPivotUp se_pvup ON se.sku_group=se_pvup.sku_group LEFT JOIN ItemData ON se.SKU=ItemData.sku GROUP BY se.size, se.size_mapped, se.sku_group, se.SKU, sc.num_size_available, sr.size_ratio_percentage, se_pvup.XS_units_store, se_pvup.S_units_store, se_pvup.M_units_store, se_pvup.L_units_store, se_pvup.XL_units_store, se_pvup.XXL_units_store, se_pvup.XL3_units_store, se_pvup.XL4_units_store, se_pvup.XL5_units_store, se_pvup.XL6_units_store, se_pvup.XL7_units_store, se_pvup.XL8_units_store, se_pvup.NA_units_store, ItemData.first_sale_date, ItemData.days_elapsed ), ReplenData AS ( SELECT fd.*, am.id, am.price, am.product_name, UPPER(am.category) AS availability_category, am.xs_units, am.s_units, am.m_units, am.l_units, am.xl_units, am.xxl_units, am.xl3_units, am.xl4_units, am.xl5_units, am.xl6_units, am.na_units, am.xl7_units, am.xl8_units, am.sellable_inventory, am.sku_class, am.num_size_available AS num_size_wh, CASE WHEN fd.FINAL_NATURAL_RATE_OF_SALE < fd.FINAL_SEVEN_DAY_RATE_OF_SALE THEN fd.FINAL_SEVEN_DAY_RATE_OF_SALE ELSE fd.FINAL_NATURAL_RATE_OF_SALE END AS final_ros, CASE WHEN fd.DAYS_ELAPSED >= 4 THEN ROUND( CASE WHEN ((CASE WHEN fd.FINAL_NATURAL_RATE_OF_SALE < fd.FINAL_SEVEN_DAY_RATE_OF_SALE THEN fd.FINAL_SEVEN_DAY_RATE_OF_SALE ELSE fd.FINAL_NATURAL_RATE_OF_SALE END)*30 - fd.UNITS_ON_HAND) < 0 THEN 0 ELSE ((CASE WHEN fd.FINAL_NATURAL_RATE_OF_SALE < fd.FINAL_SEVEN_DAY_RATE_OF_SALE THEN fd.FINAL_SEVEN_DAY_RATE_OF_SALE ELSE fd.FINAL_NATURAL_RATE_OF_SALE END)*30 - fd.UNITS_ON_HAND) END,0) ELSE 0 END AS replen_nocap, CASE WHEN SIZE_MAPPED = \'NA\' THEN replen_nocap WHEN replen_nocap >= 6 THEN 6 ELSE replen_nocap END AS replen_cap FROM FinalData fd LEFT JOIN snitch_db.maplemonk.availability_master_v2 am ON fd.sku_group = am.sku_group ), ReplenRatio AS ( SELECT sku_group, SUM(replen_nocap) AS total_replen_cap_per_group FROM ReplenData GROUP BY sku_group ) SELECT rd.*, CASE WHEN round(rr.total_replen_cap_per_group * rd.SIZE_RATIO_PERCENTAGE / NULLIF(rd.sum_size_ratio_percentage_by_sku_group, 0),0) is null THEN 0 ELSE round(rr.total_replen_cap_per_group * rd.SIZE_RATIO_PERCENTAGE / NULLIF(rd.sum_size_ratio_percentage_by_sku_group, 0),0) END AS replen_sale_ratio, CASE WHEN rd.SIZE_MAPPED = \'NA\' THEN replen_sale_ratio WHEN replen_sale_ratio < 6 THEN replen_sale_ratio ELSE 6 END AS replen_sale_ratio_capped, CASE WHEN total_replen_cap_per_group >0 AND replen_cap = 0 AND units_on_hand=0 THEN 1 ELSE 0 END AS addl_replen_sizes, (replen_cap+addl_replen_sizes) as replen_1 FROM ReplenData rd LEFT JOIN ReplenRatio rr ON rd.sku_group = rr.sku_group ORDER BY rd.units_on_hand DESC;",
